import {storefrontData} from './storefront-data.js';
import {esc,money,icon,openModal,closeModal,toast,confirm} from './ui.js';

const sections=[['files','내신 PDF·한글'],['bstore','B서점 (실물책)'],['pod','POD 서점']];
const views=new Map();
let disposeDetail=()=>{};
const CART_KEY='mathsecr-storefront-cart-v1';
const ORDER_KEY='mathsecr-storefront-orders-v1';
const maxQuantity=Number.MAX_SAFE_INTEGER;
const num=value=>Number.isFinite(Number(value))?Number(value):0;
const quantity=value=>Math.min(maxQuantity,Math.max(1,Math.floor(num(value)||1)));
const catalog=()=>({files:storefrontData.school||[],bstore:storefrontData.bstore||[],pod:storefrontData.pod||[]});
const findProduct=(section,id)=>catalog()[section]?.find(p=>String(p.id)===String(id));
const productPrice=(p,format)=>format==='pdf'?p.pdfPrice:format==='hwp'?p.hwpPrice:p.price;
const difficultyNames=['쉬움','보통','어려움','매우 어려움'];
const difficultyValues=p=>Array.isArray(p.difficultyCounts)?p.difficultyCounts:difficultyNames.map((name,i)=>p.difficultyCounts?.[name]??p.difficultyCounts?.[['easy','normal','hard','veryHard'][i]]??0);
const imageList=value=>(Array.isArray(value)?value:[]).map(x=>typeof x==='string'?x:x?.src).filter(Boolean);
const textList=value=>Array.isArray(value)?value:typeof value==='string'?[value]:[];
function stateFor(section){if(!views.has(section))views.set(section,{query:'',grade:'',subject:'',layout:'grid',selected:new Set(),format:'pdf',tab:'detail',fileTab:'search',showRange:true,hidePurchased:false,sort:'newest'});return views.get(section);}
function normalizeOptions(product,input={}){if(!product.customization)return null;input=input||{};const settings=product.customization,style=settings.styles?.find(s=>s.id===input.style&&s.available)?.id||'basic',cover=settings.covers?.find(c=>c.id===input.coverId)?.id||'';return {style,academy:style==='academy'?String(input.academy||'').trim().slice(0,60):'',region:style==='academy'?String(input.region||'').trim().slice(0,60):'',coverId:style==='academy'?cover:'',logoName:style==='academy'?String(input.logoName||'').slice(0,150):''};}
function minimumCopies(product,options){return product.customization?.styles?.find(s=>s.id===(options?.style||'basic'))?.minCopies||1;}
function lineQuantity(product,options,value){return Math.min(product.maxCopies||Number.MAX_SAFE_INTEGER,Math.max(minimumCopies(product,options),quantity(value)));}
function optionDescription(product,options){if(!options)return'';const style=product.customization?.styles?.find(s=>s.id===options.style)?.label||'기본 디자인';const cover=product.customization?.covers?.find(c=>c.id===options.coverId)?.label;return [style,options.academy,options.region,cover,options.logoName].filter(Boolean).join(' · ');}
function readCart(){try{const value=JSON.parse(localStorage.getItem(CART_KEY)||'[]');return (Array.isArray(value)?value:[]).flatMap(item=>{const p=findProduct(item.section,item.id);if(!p||!['files','bstore','pod'].includes(item.section))return[];const format=item.section==='files'?(item.format==='hwp'?'hwp':'pdf'):'';if(productPrice(p,format)==null)return[];const options=normalizeOptions(p,item.options);return[{section:item.section,id:p.id,format,quantity:item.section==='files'?1:lineQuantity(p,options,item.quantity),...(options?{options}:{})}];});}catch{return[];}}
function writeCart(items){try{localStorage.setItem(CART_KEY,JSON.stringify(items));return true;}catch{toast('브라우저 저장 공간을 사용할 수 없어 장바구니를 저장하지 못했어요.');return false;}}
function cartKey(item){return `${item.section}/${item.id}/${item.format||''}/${item.options?encodeURIComponent(JSON.stringify(item.options)):''}`;}
function cartCount(){return readCart().reduce((sum,item)=>sum+item.quantity,0);}
function addCart(section,product,format='',count=1,options=null){if(productPrice(product,format)==null){toast('이 상품의 가격을 확인할 수 없어요.');return false;}const items=readCart();const custom=normalizeOptions(product,options||{});const item={section,id:product.id,format,quantity:section==='files'?1:lineQuantity(product,custom,count),...(custom?{options:custom}:{})};const existing=items.find(x=>cartKey(x)===cartKey(item));if(existing)existing.quantity=section==='files'?1:lineQuantity(product,custom,existing.quantity+item.quantity);else items.push(item);return writeCart(items);}
function formatName(format){return format==='pdf'?'PDF':format==='hwp'?'한글':'';}
function difficulty(p){const values=difficultyValues(p);return `<span class="sf-difficulties" aria-label="${esc(values.map((n,i)=>`${difficultyNames[i]} ${n}`).join(', '))}">${values.map((n,i)=>`<span style="--sf-level:${['#dd8500','#00764b','#ff4f4f','#494952'][i]}">${esc(n)}</span>`).join('')}</span>`;}
function productMeta(p){return [p.grade,p.subject,p.publisher].filter(Boolean).join(' · ');}
function renderEmpty(message='검색 결과가 없어요.'){return `<div class="sf-empty">${icon('search')}<strong>${esc(message)}</strong><span>다른 검색어나 조건을 선택해 주세요.</span></div>`;}
function header(section,title){return `<header class="sf-header"><h1>${esc(title||'상점')}</h1><button class="sf-cart-button" data-cart>장바구니 <span data-cart-count>${cartCount()}</span></button></header><nav class="sf-nav" aria-label="수학B서점 메뉴">${sections.map(([key,label])=>`<a href="#shop/${key}" ${section===key?'aria-current="page"':''}>${storefrontData.icons?.[key]?`<img src="${esc(storefrontData.icons[key])}" alt="">`:''}${label}</a>`).join('')}</nav>`;}
function refreshCartCount(container){container.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=cartCount());}
function safeGo(ctx,path){ctx.go(path);}
function filterProducts(products,state){const query=state.query.trim().toLocaleLowerCase('ko');return products.filter(p=>(!state.grade||p.grade===state.grade)&&(!state.subject||p.subject===state.subject)&&(!query||[p.title,p.school,p.region,p.subject,p.publisher,p.grade,p.year].filter(Boolean).join(' ').toLocaleLowerCase('ko').includes(query)));}
function filters(products,state,section){const options=key=>[...new Set(products.map(p=>p[key]).filter(Boolean))];return `<form class="sf-search" data-search><label class="sf-search-input">${icon('search')}<input name="query" aria-label="${section==='files'?'학교·자료명':'교재명·출판사'} 검색" placeholder="${section==='files'?'학교명 또는 자료명을 검색해 주세요.':'교재명 또는 출판사를 검색해 주세요.'}" value="${esc(state.query)}"></label><button class="btn primary" type="submit">검색</button></form><div class="sf-filter-row"><label>학년<select data-filter="grade"><option value="">전체</option>${options('grade').map(v=>`<option ${state.grade===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>과목<select data-filter="subject"><option value="">전체</option>${options('subject').map(v=>`<option ${state.subject===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><button class="sf-reset" data-reset>${icon('close')}초기화</button></div>`;}
function readOrders(){try{const rows=JSON.parse(localStorage.getItem(ORDER_KEY)||'[]');return Array.isArray(rows)?rows.filter(order=>order&&order.simulation&&Array.isArray(order.items)):[];}catch{return[];}}
function fileHistoryIds(){return new Set(readOrders().flatMap(order=>order.items.filter(item=>item.section==='files').map(item=>item.id)));}
function fileFilters(state){return `<div class="sf-file-search-row"><div class="sf-file-tabs" role="tablist" aria-label="내신 파일 검색"><button role="tab" aria-selected="${state.fileTab==='search'}" tabindex="${state.fileTab==='search'?0:-1}" data-file-tab="search">빠르게 검색</button><button role="tab" aria-selected="${state.fileTab==='history'}" tabindex="${state.fileTab==='history'?0:-1}" data-file-tab="history">구매 내역</button></div><form class="sf-search sf-file-search" data-search><label class="sf-search-input">${icon('search')}<input name="query" aria-label="내신 파일 통합검색" placeholder="연도, 지역, 학교, 학년, 학기, 과목 검색" value="${esc(state.query)}"></label><button class="sf-search-submit" type="submit" aria-label="검색">${icon('search')}</button></form></div><div class="sf-file-tools"><button class="sf-unit-select" data-unit-select>${esc(state.subject||'단원 및 유형 선택(신교육)')}${icon('chevron-down')}</button><div><select data-file-sort aria-label="정렬"><option value="newest" ${state.sort==='newest'?'selected':''}>출제 최신순</option><option value="title" ${state.sort==='title'?'selected':''}>제목순</option></select><label><input type="checkbox" data-hide-purchased ${state.fileTab==='history'?'disabled':state.hidePurchased?'checked':''}>구매내역 숨기기</label><label><input type="checkbox" data-show-range ${state.showRange?'checked':''}>시험범위 보기</label></div></div>${state.fileTab==='history'?'<p class="sf-history-note">이 브라우저에서 저장한 체험 주문만 표시합니다. 실제 구매 내역이 아닙니다.</p>':''}`;}
function unitModal(products,state,onApply){const subjects=[...new Set(products.map(p=>p.subject).filter(Boolean))];openModal({title:'단원 및 유형 선택',body:`<div class="sf-unit-tabs"><span>신 교육과정</span></div><div class="sf-unit-choices"><label><input type="radio" name="sf-course" value="" ${!state.subject?'checked':''}>전체</label>${subjects.map(subject=>`<label><input type="radio" name="sf-course" value="${esc(subject)}" ${state.subject===subject?'checked':''}>${esc(subject)}</label>`).join('')}</div><div class="sf-unit-ranges">${products.map(p=>`<p><strong>${esc(p.subject)}</strong>${esc(p.range)}</p>`).join('')}</div><p class="sf-prototype-note">현재 확인한 내신 자료의 과목과 시험범위로 검색합니다.</p>`,footer:'<button class="btn" data-unit-reset>초기화</button><button class="btn primary" data-unit-apply>적용</button>',onMount:dialog=>{dialog.querySelector('[data-unit-reset]').onclick=()=>{state.subject='';closeModal();onApply();};dialog.querySelector('[data-unit-apply]').onclick=()=>{state.subject=dialog.querySelector('[name="sf-course"]:checked').value;closeModal();onApply();};}});}
function filesTable(products,state){return `<div class="sf-file-table-wrap"><table class="sf-file-table"><thead><tr>${state.showRange?'<th class="sf-range-heading">시험범위(신교육)</th>':''}<th class="sf-title-heading">제목</th><th class="sf-cost-heading">PDF파일</th><th class="sf-cost-heading">한글파일</th><th class="sf-db-heading">DB</th></tr></thead><tbody>${products.map(p=>`<tr>${state.showRange?`<td class="sf-range">${esc(p.range||[p.subject,p.term,p.exam].filter(Boolean).join(' · '))}</td>`:''}<td><button class="sf-file-title" data-preview="${esc(p.id)}">${esc(p.title)}</button><div class="sf-file-stats"><strong>${esc(p.questionCount??'—')}문제</strong><span>평균 <b>${p.avgDifficulty!=null?Number(p.avgDifficulty).toFixed(1):'—'}</b></span><span>난이도</span>${difficulty(p)}${p.answerIncluded?'<span class="sf-answer-tag">정답</span>':''}</div></td><td><button class="sf-price-button" data-file-add="${esc(p.id)}" data-format="pdf" ${p.pdfPrice==null?'disabled':''}>${money(p.pdfPrice)}<small>${icon('plus')} 담기</small></button></td><td><button class="sf-price-button" data-file-add="${esc(p.id)}" data-format="hwp" ${p.hwpPrice==null?'disabled':''}>${money(p.hwpPrice)}<small>${icon('plus')} 담기</small></button></td><td><button class="btn small sf-db-buy" data-file-db="${esc(p.id)}">구매하기</button></td></tr>`).join('')}</tbody></table></div>`;}
function storeIcon(name,fallback=''){const src=storefrontData.icons?.[name];return src?`<img src="${esc(src)}" alt="" aria-hidden="true">`:fallback;}
function statsBox(product){return `<div class="sf-stats-box"><div><span>평균</span><strong>${product.avgDifficulty!=null?Number(product.avgDifficulty).toFixed(1):'—'}</strong></div><hr><div><span>난이도</span>${difficulty(product)}</div></div>`;}
function priceBlock(product){return `<div class="sf-original-price">${product.listPrice!=null&&product.listPrice!==product.price?`<div><del>${money(product.listPrice)}</del><span>${esc(product.discountPercent??Math.round((1-product.price/product.listPrice)*100))}% 할인</span></div>`:''}<strong>${money(product.price)}</strong><p data-shipping-label>${esc([product.shippingLabel,product.pointsRate!=null?`${product.pointsRate}% 포인트 적립`:null].filter(Boolean).join(' · '))}</p></div>`;}
function productTile(p,section,layout){if(layout==='list')return productListRow(p,section);return `<article class="sf-product ${layout==='list'?'sf-product-row':''}"><a href="#shop/${section}/${encodeURIComponent(p.id)}" class="sf-product-link"><div class="sf-cover">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(p.title)} 표지" loading="lazy">`:''}</div><div class="sf-product-info"><h2>${esc(p.title)}</h2><div class="sf-product-question-info"><p>문제:${esc(p.questionCount??'—')} 해설:${esc(p.answerCount??'—')}</p>${statsBox(p)}</div><p class="sf-product-publisher">${esc(p.publisher||'')}</p>${priceBlock(p)}${p.isNew?'<span class="sf-new">New</span>':''}</div></a></article>`;}
function productListRow(p,section){return `<article class="sf-product-row-original"><a href="#shop/${section}/${encodeURIComponent(p.id)}"><div class="sf-row-cover"><img src="${esc(p.cover)}" alt="${esc(p.title)} 표지" loading="lazy"></div><div class="sf-row-info"><div><h2>${esc(p.title)}${p.isNew?'<span class="sf-new">New</span>':''}</h2><div class="sf-row-meta"><span>${esc(p.questionCount)}문제 ${esc(p.answerCount)}해설</span><span class="sf-row-difficulty">평균 <b>${Number(p.avgDifficulty).toFixed(1)}</b> 난이도 ${difficulty(p)}</span><span>${esc(p.publisher||'')}</span></div></div><div><p>${p.pointsRate!=null?`${p.pointsRate}% 포인트 적립`:''}</p><div class="sf-row-price">${p.listPrice&&p.listPrice!==p.price?`<del>${money(p.listPrice)}</del><em>${esc(p.discountPercent??Math.round((1-p.price/p.listPrice)*100))}% 할인</em>`:''}<strong>${money(p.price)}</strong><span>${esc(p.shippingLabel||'')}</span></div></div></div></a><div class="sf-row-purchase"><button class="btn" data-list-add="${esc(p.id)}">담기</button><button class="btn primary" data-list-buy="${esc(p.id)}">바로 구매</button></div></article>`;}
function viewToggleIcon(view){const src=storefrontData.icons?.[view==='grid'?'cardSelected':'list'];return src?`<span class="sf-view-icon" style="--sf-view-icon:url('${esc(src)}')" aria-hidden="true"></span>`:'';}
function bookToolbar(products,state,section){const publishers=section==='pod'?[...new Set(products.map(p=>p.publisher).filter(Boolean))]:[];return `<div class="sf-book-toolbar"><div class="sf-book-search-row"><form class="sf-book-search" data-search><input name="query" aria-label="검색" placeholder="검색어 입력" value="${esc(state.query)}"><button type="submit" aria-label="검색">${storeIcon('search',icon('search'))}</button></form><div class="sf-view-toggle" aria-label="보기 방식">${['grid','list'].map(view=>`<button data-view="${view}" aria-label="${view==='grid'?'카드':'리스트'} 보기" aria-pressed="${state.layout===view}">${viewToggleIcon(view)}</button>`).join('')}</div></div><div class="sf-publisher-tabs" role="tablist" aria-label="출판사"><button role="tab" data-publisher="" aria-selected="${!state.publisher}">전체</button>${publishers.map(name=>`<button role="tab" data-publisher="${esc(name)}" aria-selected="${state.publisher===name}">${esc(name)}<span class="sf-publisher-new">N</span></button>`).join('')}</div></div>`;}
function banner(section,state={}){if(section==='bstore'){const entries=storefrontData.banners?.bstore?.items||[];if(!entries.length)return'';const current=(state.bannerIndex??storefrontData.banners.bstore.initialIndex??0)%entries.length;return `<section class="sf-banner-carousel" aria-label="상점 배너"><div class="sf-banner-track"><div class="sf-banner-slots">${Array.from({length:Math.min(3,entries.length)},(_,i)=>{const b=entries[(current+i)%entries.length];return `<div class="sf-banner-slot">${b.url?`<a href="${esc(b.url)}" ${b.url.startsWith('#')?'':'target="_blank" rel="noopener"'}>`:''}<img src="${esc(b.image)}" alt="${esc(b.title)}">${b.url?'</a>':''}</div>`;}).join('')}</div><button class="sf-banner-prev" data-banner-step="-1" aria-label="이전 배너 보기">${storeIcon('left',icon('chevron-left'))}</button><button class="sf-banner-next" data-banner-step="1" aria-label="다음 배너 보기">${storeIcon('right',icon('chevron'))}</button></div><div class="sf-banner-dots">${entries.map((b,i)=>`<button data-banner-index="${i}" aria-label="배너 ${i+1}로 이동" ${current===i?'aria-current="true"':''}><span></span></button>`).join('')}</div></section>`;}const b=storefrontData.banners?.[section==='files'?'school':section];if(!b)return'';return `<section class="sf-banner sf-banner-${section}" style="--sf-banner-bg:${esc(b.background||'#357cef')}"><div><h2>${esc(b.title)}</h2><p>${esc(b.description)}</p></div>${b.image?`<img src="${esc(b.image)}" alt="" aria-hidden="true">`:''}</section>`;}
function renderList(container,ctx,section){const state=stateFor(section),products=catalog()[section];let results=filterProducts(products,state);if(section==='files'){const purchased=fileHistoryIds();results=results.filter(p=>(state.fileTab!=='history'||purchased.has(p.id))&&(!state.hidePurchased||!purchased.has(p.id)));results.sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title,'ko'):num(b.year)-num(a.year));}else if(state.publisher)results=results.filter(p=>p.publisher===state.publisher);
 container.innerHTML=`<div class="sf-workspace sf-list-workspace">${header(section)}${banner(section,state)}${section==='files'?fileFilters(state):bookToolbar(products,state,section)}${results.length?section==='files'?filesTable(results,state):`<div class="sf-products ${state.layout==='list'?'is-list':''}">${results.map(p=>productTile(p,section,state.layout)).join('')}</div>`:renderEmpty()}</div>`;
 container.querySelector('[data-cart]').onclick=()=>cartModal(container,ctx);
 container.querySelector('[data-search]').onsubmit=e=>{e.preventDefault();state.query=new FormData(e.currentTarget).get('query')||'';renderList(container,ctx,section);};
 container.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{state.layout=el.dataset.view;renderList(container,ctx,section);});
 container.querySelectorAll('[data-list-add]').forEach(el=>el.onclick=()=>{if(addCart(section,findProduct(section,el.dataset.listAdd))){refreshCartCount(container);toast('장바구니에 담았어요.');}});
 container.querySelectorAll('[data-list-buy]').forEach(el=>el.onclick=()=>{const product=findProduct(section,el.dataset.listBuy),options=normalizeOptions(product);checkout([{section,id:product.id,format:'',quantity:1,...(options?{options}:{})}],container,ctx,false);});
 container.querySelectorAll('[data-publisher]').forEach(el=>el.onclick=()=>{state.publisher=el.dataset.publisher;renderList(container,ctx,section);});
 container.querySelectorAll('[data-banner-step]').forEach(el=>el.onclick=()=>{const length=storefrontData.banners.bstore.items.length;state.bannerIndex=((state.bannerIndex??storefrontData.banners.bstore.initialIndex??0)+Number(el.dataset.bannerStep)+length)%length;renderList(container,ctx,section);});
 container.querySelectorAll('[data-banner-index]').forEach(el=>el.onclick=()=>{state.bannerIndex=Number(el.dataset.bannerIndex);renderList(container,ctx,section);});
 container.querySelectorAll('[data-file-add]').forEach(el=>el.onclick=()=>{if(addCart(section,findProduct(section,el.dataset.fileAdd),el.dataset.format)){refreshCartCount(container);toast('장바구니에 담았어요.');}});
 container.querySelectorAll('[data-preview]').forEach(el=>el.onclick=()=>filePreview(findProduct('files',el.dataset.preview),container,ctx));
 container.querySelectorAll('[data-file-tab]').forEach(el=>{el.onclick=()=>{state.fileTab=el.dataset.fileTab;renderList(container,ctx,section);};el.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();state.fileTab=e.key==='Home'?'search':e.key==='End'?'history':state.fileTab==='search'?'history':'search';renderList(container,ctx,section);container.querySelector(`[data-file-tab="${state.fileTab}"]`).focus();}};});
 const unit=container.querySelector('[data-unit-select]');if(unit)unit.onclick=()=>unitModal(products,state,()=>renderList(container,ctx,section));
 const sort=container.querySelector('[data-file-sort]');if(sort)sort.onchange=()=>{state.sort=sort.value;renderList(container,ctx,section);};
 const hide=container.querySelector('[data-hide-purchased]');if(hide)hide.onchange=()=>{state.hidePurchased=hide.checked;renderList(container,ctx,section);};
 const range=container.querySelector('[data-show-range]');if(range)range.onchange=()=>{state.showRange=range.checked;renderList(container,ctx,section);};
 container.querySelectorAll('[data-file-db]').forEach(el=>el.onclick=()=>{const p=findProduct('files',el.dataset.fileDb),db=p.linkedDBId&&ctx.dbs.find(d=>d.id===p.linkedDBId);if(db){ctx.openDB(db.id);return;}openModal({title:'내신 DB 안내',body:'<p>이 시험지와 연결된 DB는 현재 체험 표본에 포함하지 않았습니다.</p>',footer:'<button class="btn primary" data-open-library>내신 DB 둘러보기</button>',onMount:dialog=>dialog.querySelector('[data-open-library]').onclick=()=>{closeModal();safeGo(ctx,'library/school');}});});
}
function filePreview(product,container,ctx){if(!product)return;const images=imageList(product.previewImages||product.sampleImages);openModal({title:product.title,wide:true,body:`<div class="sf-preview-meta"><span>${esc([product.grade,product.subject].filter(Boolean).join(' · '))}</span><span>${esc(product.questionCount??'—')}문항 · 평균 난이도 ${esc(product.avgDifficulty??'—')}</span>${difficulty(product)}</div>${images.length?`<div class="sf-file-preview">${images.map((src,i)=>`<img src="${esc(src)}" alt="${esc(product.title)} 미리보기 ${i+1}페이지">`).join('')}</div>`:'<p class="sf-empty-note">이 표본의 미리보기 이미지를 아직 확보하지 못했어요.</p>'}<p class="sf-prototype-note">${esc(product.previewNote||'미리보기 표본입니다. 전체 시험지 파일은 아닙니다.')} 실제 PDF·한글 파일 구매와 내려받기는 연결하지 않았습니다.</p>`,footer:`<button class="btn" data-buy-format="pdf" ${product.pdfPrice==null?'disabled':''}>PDF ${money(product.pdfPrice)} 담기</button><button class="btn primary" data-buy-format="hwp" ${product.hwpPrice==null?'disabled':''}>한글 ${money(product.hwpPrice)} 담기</button>`,onMount:dialog=>dialog.querySelectorAll('[data-buy-format]').forEach(el=>el.onclick=()=>{if(addCart('files',product,el.dataset.buyFormat)){refreshCartCount(container);toast('장바구니에 담았어요.');}})});}
function benefitCheck(){return '<svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path fill-rule="evenodd" clip-rule="evenodd" d="M13.7502 6.07141C13.8608 6.00489 13.9928 5.98379 14.1186 6.01255C14.2444 6.0413 14.3542 6.11766 14.4249 6.22562L14.919 6.97918C14.9834 7.07763 15.0109 7.19566 14.9968 7.31244C14.9826 7.42923 14.9277 7.53726 14.8416 7.61747L14.8401 7.61947L14.8331 7.62595L14.8047 7.6524L14.6924 7.7597C14.0711 8.36238 13.4686 8.98417 12.8858 9.62415C11.7894 10.8299 10.4874 12.4079 9.61105 13.9389C9.36651 14.3661 8.76915 14.458 8.41482 14.0892L5.17848 10.7266C5.1321 10.6783 5.09589 10.6213 5.07199 10.5588C5.04809 10.4963 5.037 10.4297 5.03938 10.3628C5.04175 10.296 5.05754 10.2303 5.08581 10.1697C5.11408 10.109 5.15425 10.0547 5.20393 10.0099L6.18207 9.1276C6.26803 9.0501 6.37825 9.00489 6.49387 8.9997C6.60948 8.99451 6.72331 9.02967 6.81586 9.09915L8.46722 10.3373C11.0468 7.79363 12.5095 6.81749 13.7502 6.07141Z" fill="currentColor"/></svg>';}
function benefitStats(title,questionCount,answerCount,counts,variant=false){return `<div class="sf-benefit-stat-card ${variant?'is-variant':''}"><h3>${title}${variant?'<small>(특정 문항에 한함)</small>':''}</h3><p>문제 ${esc(questionCount)}문항, 해설 ${esc(answerCount)}문항</p><div class="sf-benefit-difficulties">${difficultyValues({difficultyCounts:counts}).map((count,i)=>`<span><i style="background:${['#ffa310','#57ae45','#ff4f4f','#494952'][i]}"></i>${difficultyNames[i]}: ${esc(count)}</span>`).join('')}</div></div>`;}
function benefits(product){const b=product.benefits;if(!b)return'';const months=b.dbAccessMonths,duration=months===12?'1년':`${months}개월`;return `<div class="sf-benefits"><section class="sf-business-benefit">${storeIcon('complete')}<div><strong>사업자 인증하면 <mark>${esc(b.businessDiscountPercent)}%할인된 금액</mark>으로 구매 가능</strong><p>[결제 페이지]에서 인증할 수 있어요.</p></div></section><section class="sf-db-benefit"><header><strong><em>DB 사용권 제공</em> · ${duration}간 사용 가능</strong><button data-db-info>DB란 무엇인가요?</button></header><div class="sf-benefit-columns"><div class="sf-benefit-condition"><span>제공 조건</span><div><p>${benefitCheck()}<strong>동일 교재 ${esc(b.minCopies)}권 이상 구매</strong></p><p>${benefitCheck()}<strong>학생 1인당 교재 1권 (${esc(b.minStudents||b.minCopies)}명 이상)</strong></p></div><b>온 · 오프라인 구매 수량 합산 가능</b></div><span class="sf-benefit-arrow" aria-hidden="true">→</span><div class="sf-benefit-provided"><span>제공 혜택</span><div><p>${benefitCheck()}<strong>교재 DB</strong></p><p>${benefitCheck()}<strong>숫자변형 DB <small>(특정 문항에 한함)</small></strong></p></div><b>제공일로부터 ${duration} 사용 가능</b></div></div><div class="sf-benefit-description"><p>문제‧해설‧출처‧난이도까지 자동 정리된 DB 제공</p><p>DB를 통해 문제 데이터 중심으로 가공하고, 편집하고, 분석할 수 있어요.</p><p>원하는 단원이나 유형만 골라 나만의 문제지를 만들 수 있어요.</p></div><p class="sf-benefit-mydb">* 제공된 DB는 ‘<strong>나만의 DB</strong>’ 에서 확인 가능합니다.</p><div class="sf-benefit-stats">${benefitStats('해당교재',product.questionCount,product.answerCount,product.difficultyCounts)}${benefitStats('숫자변형 문제X2',b.variantQuestionCount,b.variantAnswerCount,b.variantDifficultyCounts,true)}</div></section><section class="sf-benefit-auth"><div><p><strong>수학비서 :</strong> 마이페이지 › 주문 배송 조회 › 배송 조회에서 <b>”구매확정”</b>하면 자동으로 제공돼요.</p><p><strong>외부 서점 :</strong> 구매 인증이 필요해요. 우측의 <b>“구매인증”</b> 버튼으로 인증하면 담당자 확인 후 제공돼요.</p></div><button class="btn sf-dark" data-purchase-proof>구매 인증</button></section></div>`;}
function detailInfo(product){const images=imageList(product.descriptionImages);return `<section id="sf-detail-panel" aria-labelledby="sf-detail-tab" class="sf-anchored-panel sf-information-panel">${product.supportNotice?`<div class="sf-support-notice">${storeIcon('empty')}<p>${esc(product.supportNotice)}</p>${product.supportUrl?`<a class="btn" href="${esc(product.supportUrl)}" target="_blank" rel="noopener">카페 이동</a>`:'<button class="btn" data-support-cafe>카페 이동</button>'}</div>`:''}<div class="sf-detail-images">${images.map((src,i)=>`<img src="${esc(src)}" alt="${esc(product.title)} 상세 소개 ${i+1}" loading="lazy">`).join('')}</div><div class="sf-book-information"><section class="sf-info-section"><h2>기본 정보</h2><dl>${[['발행일',product.publishedAt],['쪽수',product.pageCount!=null?`${product.pageCount}쪽`:null],['크기 및 무게',product.size],['출판사',product.publisher],['저자',product.author],['ISBN',product.isbn]].filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></section>${product.description?`<section class="sf-info-section"><h2>책 소개</h2><p class="sf-long-text">${esc(product.description)}</p></section>`:''}${product.toc?`<section class="sf-info-section"><h2>목차</h2><p class="sf-long-text">${esc(product.toc)}</p></section>`:''}</div></section>`;}
function otherPanel(tab,product){if(tab==='reviews')return `<section id="sf-reviews-panel" aria-labelledby="sf-reviews-tab" class="sf-anchored-panel sf-reviews-panel"><header><h2>구매 후기</h2><div><p>선생님들의 정성스러운 구매 후기 작성 시 <span>100P</span> 적립</p><button data-review-policy>상품 구매 후기 운영 원칙</button></div></header><div class="sf-review-summary"><div class="sf-review-stars" aria-label="등록된 별점 없음">${Array.from({length:5},()=>storeIcon('emptyStar')).join('')}</div><div class="sf-rating-bars">${['최고','좋음','보통','별로','나쁨'].map(label=>`<div><strong>${label}</strong><span></span><b>0%</b></div>`).join('')}</div></div><div class="sf-review-empty"><p>등록된 구매 후기가 없어요.</p></div></section>`;if(tab==='shipping'){const shipping=textList(product.shippingInfo),returns=textList(product.returnInfo);return `<section id="sf-shipping-panel" aria-labelledby="sf-shipping-tab" class="sf-anchored-panel sf-shipping-panel"><section><h2>배송정보</h2><ul>${shipping.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section><h2>교환, 환불, A/S 안내</h2><ul>${returns.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section></section>`;}return '';}
function podContent(product,state){const settings=product.customization||{},styles=settings.styles||[],covers=settings.covers||[];return `<div class="sf-pod-content"><section class="sf-pod-intro">${storeIcon('podLettering')}<small>POD 교재란?</small><h2>검증된 교재에 우리 학원만의 이름을 담으세요</h2><p>시중 교재의 내용은 그대로, 표지와 교재명은 원하는 대로.<br>주문한 수량만큼 인쇄·제본해 배송하는 주문형 교재예요.</p><ul><li>${storeIcon('checkPoint',icon('check'))}<div><strong>학원 로고를 담은 맞춤 표지</strong><p>표지에 학원 로고를 적용해 우리 학원만의 교재로 만들 수 있어요.<br>로고 커스텀 상품은 ${esc(settings.academyMinCopies||10)}부부터 주문 가능해요.</p></div></li><li>${storeIcon('checkPoint',icon('check'))}<div><strong>검증된 시중 교재 콘텐츠 그대로</strong><p>표지와 교재명만 바꾸고<br>원본 교재의 내용은 그대로 유지해요.</p></div></li><li>${storeIcon('checkPoint',icon('check'))}<div><strong>주문 확정 후 제작·배송</strong><p>주문 확정 후 인쇄·제본을 시작해요.<br>배송까지 영업일 기준 3~4일이 걸려요.</p></div></li><li>${storeIcon('checkPoint',icon('check'))}<div><strong>교재 해설 별도 다운로드 가능</strong><p>구매 후 [마이페이지 - 주문 배송 조회]탭에서<br>다운로드 받을 수 있어요.</p></div></li></ul></section><section class="sf-pod-db"><div><strong>이 교재는 실물 책 외에 교재 DB로도 구매할 수 있어요</strong><p>문제·해설·난이도가 정리된 DB로 나만의 문제지를 만들 수 있습니다.</p></div><button class="btn sf-dark" data-pod-db>교재 DB로 구매</button></section><section class="sf-pod-custom"><h2>디자인 스타일</h2><p>세 가지 스타일 중 희망하는 표지 스타일을 선택하세요</p><fieldset><legend><em>*</em> 디자인 스타일</legend><div class="sf-style-options">${styles.map(style=>`<label class="sf-style-option ${!style.available?'is-disabled':''}"><input type="radio" name="pod-style" value="${esc(style.id)}" ${state.style===style.id?'checked':''} ${!style.available?'disabled':''}><i aria-hidden="true"></i><span><strong>${esc(style.label)}${style.id==='academy'?`<small>${esc(style.minCopies)}부부터</small>`:style.status?`<small>${esc(style.status)}</small>`:''}</strong><span>${esc(style.description)}</span></span></label>`).join('')}</div></fieldset><div class="sf-academy-box" data-academy-fields ${state.style!=='academy'?'hidden':''}><div class="sf-academy-fields"><label><span><em>*</em> 학원 이름</span><input data-custom-field="academy" value="${esc(state.academy)}" maxlength="60" aria-required="true" placeholder="${esc(settings.academyNamePlaceholder||'예) 수비학원')}"></label><div class="sf-region-field"><span id="sf-region-label"><em>*</em> 학원 지역</span><div class="sf-region-select"><button type="button" data-region-trigger aria-labelledby="sf-region-label sf-region-value" aria-haspopup="listbox" aria-expanded="false"><span id="sf-region-value" class="${state.region?'':'is-placeholder'}">${esc(state.region||'지역 선택')}</span>${icon('chevron-down')}</button><div class="sf-region-options" role="listbox" aria-label="학원 지역" hidden>${(settings.regionOptions||[]).map(region=>`<button type="button" role="option" data-region-option="${esc(region)}" aria-selected="${state.region===region}">${esc(region)}</button>`).join('')}</div></div></div></div><div class="sf-logo-field"><strong><em>*</em> 학원 로고</strong><p>학원 로고를 넣어 우리 학원만의 표지로 만들 수 있어요.</p><div class="sf-logo-drop" data-logo-drop role="button" tabindex="0" aria-label="학원 로고 업로드"><div><p>여기로 배경이 투명한 로고 파일을 드래그하거나 <span>직접 업로드</span>하세요.</p><p class="sf-logo-instruction">업로드한 로고는 선택한 템플릿의 학원명 위치에 적용돼요. (10MB 이하의 PNG, PDF 파일만 첨부 가능)</p></div><input type="file" data-logo hidden aria-required="true" accept="image/png,application/pdf"></div><p class="sf-logo-filename" data-logo-name ${state.logoName?'':'hidden'}>${esc(state.logoName)}</p></div><fieldset class="sf-cover-picker"><legend><em>*</em> 표지 템플릿</legend><ul role="radiogroup" aria-label="표지 템플릿">${covers.map(cover=>`<li class="sf-cover-choice"><button class="sf-cover-select" type="button" role="radio" aria-checked="${state.coverId===cover.id}" data-cover="${esc(cover.id)}"><div class="sf-cover-choice-label"><i aria-hidden="true"></i><div><strong>${esc(cover.label)}</strong><small>로고 : ${esc(cover.logoPosition)}</small></div></div><div class="sf-template-image"><img src="${esc(cover.image)}" alt="${esc(cover.label)}" loading="lazy"></div></button><button type="button" class="sf-cover-preview" data-cover-preview="${esc(cover.id)}" aria-label="${esc(cover.label)} 표지 전체 보기">${storeIcon('search',icon('search'))}미리보기</button></li>`).join('')}</ul></fieldset></div></section></div>`;}
function validateCustomization(product,state,container){if(!product.customization||state.style!=='academy')return true;if(!String(state.academy||'').trim()){toast('학원 이름을 입력해 주세요.');container.querySelector('[data-custom-field="academy"]')?.focus();return false;}if(!state.region||product.customization.regionOptions?.length&&!product.customization.regionOptions.includes(state.region)){toast('학원 지역을 선택해 주세요.');container.querySelector('[data-region-trigger]')?.focus();return false;}if(product.customization.logoRequired&&!state.logoName){toast('학원 로고를 선택해 주세요.');container.querySelector('[data-logo-drop]')?.focus();return false;}if(!product.customization.covers?.some(cover=>cover.id===state.coverId)){toast('표지 템플릿을 선택해 주세요.');container.querySelector('[data-cover]')?.focus();return false;}return true;}
function coverPreview(cover){openModal({title:'제작 미리보기',wide:true,body:`<div class="sf-cover-preview-heading">표지</div><div class="sf-cover-full"><img src="${esc(cover.previewImage||cover.image)}" alt="${esc(cover.label)} 표지 전체"></div>`,onMount:dialog=>dialog.classList.add('sf-cover-preview-modal')});}
function bindPod(container,ctx,product,state,quantityInput,normalize){const updateShipping=()=>{const isAcademy=state.style==='academy',fee=isAcademy?product.customization?.academyShippingFee:num(quantityInput.value)>=(product.customization?.freeShippingSameSubjectCopies||3)?0:product.shippingFee;container.querySelector('[data-shipping-label]').textContent=[fee===0?'무료배송':fee!=null?money(fee):product.shippingLabel,product.pointsRate!=null?`${product.pointsRate}% 포인트 적립`:null].filter(Boolean).join(' · ');};
 container.querySelectorAll('[name="pod-style"]').forEach(el=>el.onchange=()=>{state.style=el.value;quantityInput.value=minimumCopies(product,state);normalize();container.querySelector('[data-academy-fields]').hidden=state.style!=='academy';updateShipping();});
 container.querySelectorAll('[data-custom-field]').forEach(el=>{const sync=()=>state[el.dataset.customField]=el.value;el.oninput=sync;el.onchange=sync;});
 const trigger=container.querySelector('[data-region-trigger]'),options=container.querySelector('.sf-region-options');const closeRegions=()=>{options.hidden=true;trigger.setAttribute('aria-expanded','false');};trigger.onclick=()=>{options.hidden=!options.hidden;trigger.setAttribute('aria-expanded',String(!options.hidden));if(!options.hidden)options.querySelector(`[aria-selected="true"]`)?.focus();};trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();options.hidden=false;trigger.setAttribute('aria-expanded','true');const items=[...options.querySelectorAll('[data-region-option]')];(e.key==='ArrowDown'?items[0]:items.at(-1))?.focus();}if(e.key==='Escape')closeRegions();};container.querySelectorAll('[data-region-option]').forEach((el,index)=>{el.onclick=()=>{state.region=el.dataset.regionOption;container.querySelector('#sf-region-value').textContent=state.region;container.querySelector('#sf-region-value').classList.remove('is-placeholder');options.querySelectorAll('[data-region-option]').forEach(button=>button.setAttribute('aria-selected',String(button===el)));closeRegions();trigger.focus();};el.onkeydown=e=>{const buttons=[...options.querySelectorAll('[data-region-option]')];if(e.key==='Escape'){closeRegions();trigger.focus();}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(index+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus();}if(e.key==='Home'||e.key==='End'){e.preventDefault();(e.key==='Home'?buttons[0]:buttons.at(-1))?.focus();}};});
 container.querySelector('.sf-academy-box').addEventListener('focusout',event=>{if(!event.relatedTarget?.closest('.sf-region-select'))closeRegions();});
 container.querySelectorAll('[data-cover]').forEach(el=>el.onclick=()=>{state.coverId=el.dataset.cover;container.querySelectorAll('[data-cover]').forEach(button=>button.setAttribute('aria-checked',String(button===el)));});
 container.querySelectorAll('[data-cover-preview]').forEach(el=>el.onclick=()=>{const cover=product.customization.covers.find(c=>c.id===el.dataset.coverPreview);if(cover)coverPreview(cover);});
 const logo=container.querySelector('[data-logo]'),drop=container.querySelector('[data-logo-drop]');const acceptLogo=file=>{if(!file)return;if(!(/\.(png|pdf)$/i.test(file.name)&&['image/png','application/pdf',''].includes(file.type))||file.size>10*1024*1024){toast('10MB 이하의 PNG, PDF 파일만 첨부할 수 있어요.');logo.value='';state.logoName='';container.querySelector('[data-logo-name]').hidden=true;return;}state.logoName=file.name;container.querySelector('[data-logo-name]').textContent=file.name;container.querySelector('[data-logo-name]').hidden=false;};logo.onchange=()=>acceptLogo(logo.files?.[0]);drop.onclick=e=>{if(e.target!==logo)logo.click();};drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();logo.click();}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('is-dragging');};drop.ondragleave=()=>drop.classList.remove('is-dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('is-dragging');acceptLogo(e.dataTransfer?.files?.[0]);};
 const previousChange=quantityInput.onchange;quantityInput.onchange=()=>{previousChange();updateShipping();};container.querySelectorAll('[data-quantity-step]').forEach(el=>{const previous=el.onclick;el.onclick=()=>{previous();updateShipping();};});updateShipping();container.querySelector('[data-pod-db]').onclick=()=>{const db=product.linkedDBId&&ctx.dbs.find(d=>d.id===product.linkedDBId);if(db){ctx.openDB(db.id);return;}openModal({title:'교재 DB 안내',body:'<p>이 상품과 연결된 교재 DB는 현재 체험 표본에 포함하지 않았습니다.</p>',footer:'<button class="btn primary" data-open-library>교재 DB 둘러보기</button>',onMount:dialog=>dialog.querySelector('[data-open-library]').onclick=()=>{closeModal();safeGo(ctx,'library/book');}});};}
function productAside(product,section,customState={}){return `<aside class="sf-purchase-panel ${section==='pod'?'sf-pod-purchase':''}" aria-label="상품 구매 정보">${product.cover?`<img class="sf-detail-cover" src="${esc(product.cover)}" alt="${esc(product.title)} 표지">`:''}<div class="sf-mini-actions ${section==='pod'?'sf-one-action':''}"><button data-sample>샘플 다운</button>${section==='pod'?'':'<button data-size>사이즈 비교</button>'}</div><div class="sf-aside-info"><h2>${esc(product.title)}</h2><div class="sf-product-question-info"><p>문제:${esc(product.questionCount??'—')} 해설:${esc(product.answerCount??'—')}</p>${statsBox(product)}</div>${product.publisher?`<p class="sf-publisher">${esc(product.publisher)}</p>`:''}${priceBlock(product)}${product.isNew?'<span class="sf-new">New</span>':''}</div><div class="sf-purchase-actions"><div class="sf-quantity"><button data-quantity-step="-1" aria-label="수량 줄이기">−</button><input type="number" data-quantity min="1" ${product.maxCopies?`max="${product.maxCopies}"`:''} step="1" value="${quantity(customState.quantity||1)}" aria-label="구매 수량"><button data-quantity-step="1" aria-label="수량 늘리기">+</button></div><div><button class="btn sf-add" data-add-detail>담기</button><button class="btn primary sf-buy" data-buy-detail ${product.price==null?'disabled':''}>바로 구매</button></div></div></aside>`;}
function renderDetail(container,ctx,section,product){const state=stateFor(`${section}/${product.id}`),tabs=[['detail',section==='pod'?'상세 정보':'상세정보'],...(section==='pod'?[]:[['reviews',`구매후기 (${product.reviewCount??0})`]]),['shipping',section==='pod'?'배송/교환/반품 정보':'배송/반품/교환'],['inquiry','상품 문의']];if(!state.custom)state.custom={style:'basic',academy:'',region:'',coverId:'',logoName:'',quantity:1};container.innerHTML=`<div class="sf-workspace sf-detail-workspace"><header class="sf-detail-header"><a href="#shop/${section}">${icon('chevron-left')}<h1>${esc(product.title)}</h1></a><button class="sf-cart-button" data-cart>장바구니 <span data-cart-count>${cartCount()}</span></button></header><div class="sf-detail-layout"><div class="sf-detail-main">${section==='pod'?podContent(product,state.custom):benefits(product)}<div class="sf-detail-tabs" role="tablist" aria-label="상품 상세 정보">${tabs.map(([key,label])=>`<button role="tab" id="sf-${key}-tab" aria-controls="sf-${key}-panel" aria-selected="${state.tab===key}" tabindex="${state.tab===key?'0':'-1'}" data-detail-tab="${key}">${label}</button>`).join('')}</div><div data-detail-content>${detailInfo(product)}${section==='bstore'?otherPanel('reviews',product):''}${otherPanel('shipping',product)}</div></div>${productAside(product,section,state.custom)}</div></div>`;
 container.querySelector('[data-cart]').onclick=()=>cartModal(container,ctx);
 const quantityInput=container.querySelector('[data-quantity]');const normalize=()=>{quantityInput.value=lineQuantity(product,state.custom,quantityInput.value);quantityInput.min=minimumCopies(product,state.custom);state.custom.quantity=Number(quantityInput.value);container.querySelector('[data-quantity-step="-1"]').disabled=num(quantityInput.value)<=minimumCopies(product,state.custom);container.querySelector('[data-quantity-step="1"]').disabled=product.maxCopies?num(quantityInput.value)>=product.maxCopies:false;};quantityInput.onchange=normalize;quantityInput.onblur=()=>quantityInput.onchange();normalize();
 container.querySelectorAll('[data-quantity-step]').forEach(el=>el.onclick=()=>{quantityInput.value=quantity(num(quantityInput.value)+num(el.dataset.quantityStep));normalize();});
 container.querySelector('[data-add-detail]').onclick=()=>{if(!validateCustomization(product,state.custom,container))return;if(addCart(section,product,'',quantityInput.value,state.custom)){refreshCartCount(container);toast('장바구니에 담았어요.');}};
 container.querySelector('[data-buy-detail]').onclick=()=>{if(!validateCustomization(product,state.custom,container))return;const options=normalizeOptions(product,state.custom);checkout([{section,id:product.id,format:'',quantity:lineQuantity(product,options,quantityInput.value),...(options?{options}:{})}],container,ctx,false);};
 container.querySelector('[data-sample]').onclick=()=>sampleModal(product);
 const size=container.querySelector('[data-size]');if(size)size.onclick=()=>sizeModal(product);if(section==='pod')bindPod(container,ctx,product,state.custom,quantityInput,normalize);
 const info=container.querySelector('[data-db-info]');if(info)info.onclick=()=>openModal({title:'DB란 무엇인가요?',body:'<p>문제와 해설에 출처·단원·난이도 정보를 함께 정리한 자료입니다. 필요한 문항을 골라 나만의 문제지로 만들 수 있어요.</p><p class="sf-prototype-note">이 상품의 DB 사용권은 실제 구매 조건을 충족한 뒤 운영 서비스에서 제공됩니다. 체험 주문으로 사용권이 생기지는 않습니다.</p>'});
 const proof=container.querySelector('[data-purchase-proof]');if(proof)proof.onclick=()=>openModal({title:'구매 인증 안내',body:'<p>외부 서점에서 구매한 교재는 운영 서비스에서 구매 인증을 신청한 뒤 담당자 확인을 받아야 합니다.</p><p class="sf-prototype-note">이 체험 화면은 인증 자료를 접수하거나 DB 사용권을 발급하지 않습니다.</p>'});
 const setActiveTab=key=>{state.tab=key;container.querySelectorAll('[data-detail-tab]').forEach(el=>{el.setAttribute('aria-selected',String(el.dataset.detailTab===key));el.tabIndex=el.dataset.detailTab===key?0:-1;});};
 const selectTab=key=>{if(key==='inquiry'){container.querySelector('.sf-detail-tabs').scrollIntoView({behavior:'auto',block:'start'});inquiryModal(product);return;}setActiveTab(key);container.querySelector(`#sf-${key}-panel`)?.scrollIntoView({behavior:'auto',block:'start'});};
 container.querySelectorAll('[data-detail-tab]').forEach(el=>{el.onclick=()=>selectTab(el.dataset.detailTab);el.onkeydown=e=>{const keys=tabs.map(([key])=>key),index=keys.indexOf(el.dataset.detailTab);let next;if(e.key==='ArrowRight')next=(index+1)%keys.length;if(e.key==='ArrowLeft')next=(index+keys.length-1)%keys.length;if(e.key==='Home')next=0;if(e.key==='End')next=keys.length-1;if(next!=null){e.preventDefault();selectTab(keys[next]);container.querySelector(`[data-detail-tab="${keys[next]}"]`).focus();}};});
 const detail=container.querySelector('.sf-detail-workspace');const trackScroll=()=>{if(!detail.isConnected){disposeDetail();return;}const offset=container.querySelector('.sf-detail-header').getBoundingClientRect().bottom+48+2;let current='detail';for(const key of ['detail','reviews','shipping']){const panel=container.querySelector(`#sf-${key}-panel`);if(panel&&panel.getBoundingClientRect().top<=offset)current=key;}setActiveTab(current);};
 window.addEventListener('scroll',trackScroll,{passive:true,capture:true});window.addEventListener('hashchange',disposeOnRoute);function disposeOnRoute(){disposeDetail();}disposeDetail=()=>{window.removeEventListener('scroll',trackScroll,true);window.removeEventListener('hashchange',disposeOnRoute);disposeDetail=()=>{};};setActiveTab('detail');
 const support=container.querySelector('[data-support-cafe]');if(support)support.onclick=()=>openModal({title:'카페 이동',body:'<p>이 교재의 카페 주소를 아직 확인하지 못했습니다.</p>'});const policy=container.querySelector('[data-review-policy]');if(policy)policy.onclick=()=>openModal({title:'상품 구매 후기 운영 원칙',body:'<p>운영 서비스의 상품 구매 후기 운영 원칙을 아직 확인하지 못했습니다.</p>'});
}
function inquiryModal(product){const info=product.inquiry;if(!info){openModal({title:'상품 문의',body:'<p>이 상품의 문의처를 아직 확인하지 못했습니다.</p>'});return;}openModal({title:'상품 문의',body:`<p class="sf-inquiry-description">${esc(info.description)}</p>${info.phone?`<a class="sf-inquiry-phone" href="tel:${esc(info.phone)}">전화 문의 (${esc(info.phone)})</a>`:''}${info.customerServiceUrl?`<a class="sf-inquiry-support" href="${esc(info.customerServiceUrl)}" target="_blank" rel="noopener">수학비서 고객센터</a>`:''}`,onMount:dialog=>dialog.classList.add('sf-inquiry-modal')});}
function sampleModal(product){const images=imageList(product.sampleImages);openModal({title:`${product.title} · 샘플`,wide:true,body:images.length?`<div class="sf-sample-pages">${images.map((src,i)=>`<img src="${esc(src)}" alt="${esc(product.title)} 샘플 ${i+1}">`).join('')}</div>`:'<p class="sf-empty-note">이 상품의 샘플 파일을 아직 확보하지 못했습니다.</p>',footer:product.sampleUrl?`<a class="btn primary" href="${esc(product.sampleUrl)}" target="_blank" rel="noopener">샘플 파일 열기</a>`:''});}
function sizeModal(product){const a=product.sizeReferenceSize,b=product.sizeComparisonSize;if(!a||!b||!product.sizeReferenceImage||!product.sizeComparisonImage){openModal({title:'사이즈 비교',body:'<p>이 상품의 사이즈 비교 이미지를 아직 확보하지 못했습니다.</p>'});return;}const gap=60,x=a.width+gap,h=Math.max(a.height,b.height),total=a.width+b.width+gap;const dimension=(width,height,left)=>`<svg x="${left}" y="${h-height}" width="${width}" height="${height}" overflow="visible"><path d="M0 0 Q${width/2} -35 ${width} 0" fill="none" stroke="white" stroke-width="1" stroke-dasharray="2,3"/><text x="${width/2}" y="-25" text-anchor="middle" fill="white" font-size="12">${width}mm</text><path d="${left?`M${width} 0 Q${width+30} ${height/2} ${width} ${height}`:`M0 0 Q-30 ${height/2} 0 ${height}`}" fill="none" stroke="white" stroke-width="1" stroke-dasharray="2,3"/><text x="${left?width+45:-45}" y="${height/2}" text-anchor="middle" fill="white" font-size="12">${height}mm</text></svg>`;openModal({title:'사이즈 비교',body:`<svg class="sf-size-visual" viewBox="-120 -50 ${total+240} ${h+100}" role="img" aria-label="A4 ${a.width} × ${a.height}mm, ${esc(product.title)} ${b.width} × ${b.height}mm">${dimension(a.width,a.height,0)}${dimension(b.width,b.height,x)}<image href="${esc(product.sizeReferenceImage)}" x="0" y="${h-a.height}" width="${a.width}" height="${a.height}" preserveAspectRatio="none"/><text x="${a.width/2}" y="${h-a.height/2}" text-anchor="middle" dominant-baseline="middle" fill="black" font-size="40" font-weight="700">A4</text><image href="${esc(product.sizeComparisonImage)}" x="${x}" y="${h-b.height}" width="${b.width}" height="${b.height}" preserveAspectRatio="none"/><text x="${a.width/2}" y="${h+34}" text-anchor="middle" fill="white" font-size="16" font-weight="700">A4용지</text><text x="${x+b.width/2}" y="${h+34}" text-anchor="middle" fill="#fff570" font-size="16" font-weight="600">${esc(product.title)}</text></svg>`,onMount:dialog=>{dialog.classList.add('sf-size-modal');dialog.tabIndex=-1;dialog.focus();dialog.querySelector('.modal-body').onclick=e=>{if(e.target===e.currentTarget)closeModal();};}});}
function cartModal(container,ctx){const items=readCart(),total=items.reduce((sum,item)=>sum+num(productPrice(findProduct(item.section,item.id),item.format))*item.quantity,0);openModal({title:'장바구니',wide:true,body:`${items.length?`<div class="sf-cart-list">${items.map(item=>{const p=findProduct(item.section,item.id);return `<article class="sf-cart-item">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(p.title)} 표지">`:`<span class="sf-cart-file">${formatName(item.format)}</span>`}<div class="sf-cart-description"><strong>${esc(p.title)}</strong><small>${esc(formatName(item.format)||sections.find(([key])=>key===item.section)?.[1])}</small>${item.options?`<small>${esc(optionDescription(p,item.options))}</small>`:''}<span>${money(productPrice(p,item.format))}</span></div><label class="sf-cart-qty">수량<input type="number" data-cart-qty="${esc(cartKey(item))}" value="${item.quantity}" min="${minimumCopies(p,item.options)}" ${item.section==='files'?'max="1"':p.maxCopies?`max="${p.maxCopies}"`:''} ${item.section==='files'?'readonly':''} aria-label="${esc(p.title)} 수량"></label><strong>${money(num(productPrice(p,item.format))*item.quantity)}</strong><button class="sf-icon-button" data-remove="${esc(cartKey(item))}" aria-label="${esc(p.title)} 삭제">${icon('trash')}</button></article>`;}).join('')}</div><div class="sf-cart-total"><span>상품 합계</span><strong>${money(total)}</strong></div><p class="sf-prototype-note">배송비·인증 할인·포인트는 실제 주문 단계에서 확인해야 합니다. 이 합계는 상품 금액만 표시합니다.</p>`:'<div class="sf-empty-note">장바구니가 비어 있어요.</div>'}`,footer:`<button class="btn" data-continue>계속 둘러보기</button>${items.length?'<button class="btn primary" data-checkout>주문하기</button>':''}`,onMount:dialog=>{dialog.classList.add('sf-cart-modal');dialog.querySelector('[data-continue]').onclick=closeModal;dialog.querySelectorAll('[data-cart-qty]').forEach(el=>el.onchange=()=>{const updated=readCart(),item=updated.find(x=>cartKey(x)===el.dataset.cartQty);if(item){item.quantity=item.section==='files'?1:lineQuantity(findProduct(item.section,item.id),item.options,el.value);if(writeCart(updated)){refreshCartCount(container);cartModal(container,ctx);}}});dialog.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>confirm({title:'장바구니에서 삭제할까요?',body:'선택한 상품을 장바구니에서 삭제합니다.',onConfirm:()=>{writeCart(readCart().filter(item=>cartKey(item)!==el.dataset.remove));refreshCartCount(container);cartModal(container,ctx);}}));const order=dialog.querySelector('[data-checkout]');if(order)order.onclick=()=>checkout(readCart(),container,ctx,true);}});}
function checkout(items,container,ctx,fromCart){const valid=items.filter(item=>findProduct(item.section,item.id));if(!valid.length){toast('주문할 상품을 선택해 주세요.');return;}const total=valid.reduce((sum,item)=>sum+num(productPrice(findProduct(item.section,item.id),item.format))*item.quantity,0);openModal({title:'체험 주문 확인',body:`<p class="sf-cart-notice">실제 결제·배송·다운로드를 신청하는 화면이 아닙니다. 상품과 수량을 확인하는 로컬 체험입니다.</p><div class="sf-order-summary">${valid.map(item=>`<div><span>${esc(findProduct(item.section,item.id).title)}${item.format?` (${formatName(item.format)})`:''}<small>${item.quantity}개${item.options?` · ${esc(optionDescription(findProduct(item.section,item.id),item.options))}`:''}</small></span><strong>${money(num(productPrice(findProduct(item.section,item.id),item.format))*item.quantity)}</strong></div>`).join('')}</div><div class="sf-cart-total"><span>상품 합계</span><strong>${money(total)}</strong></div><p class="sf-prototype-note">배송비, 사업자 인증 할인, 포인트 사용·적립은 반영하지 않습니다. 체험 주문은 DB 이용 권한을 부여하지 않습니다.</p><label class="sf-order-agree"><input type="checkbox" data-agree>실제 주문이 아닌 로컬 체험임을 확인했습니다.</label>`,footer:'<button class="btn" data-cancel>취소</button><button class="btn primary" data-confirm-order disabled>체험 주문 저장</button>',onMount:dialog=>{dialog.querySelector('[data-cancel]').onclick=()=>fromCart?cartModal(container,ctx):closeModal();const save=dialog.querySelector('[data-confirm-order]');dialog.querySelector('[data-agree]').onchange=e=>save.disabled=!e.target.checked;save.onclick=()=>{try{const old=JSON.parse(localStorage.getItem(ORDER_KEY)||'[]');const orders=Array.isArray(old)?old:[];orders.push({id:globalThis.crypto?.randomUUID?.()||String(Date.now()),createdAt:new Date().toISOString(),items:valid,total,simulation:true});localStorage.setItem(ORDER_KEY,JSON.stringify(orders.slice(-50)));if(fromCart){const keys=new Set(valid.map(cartKey));writeCart(readCart().filter(item=>!keys.has(cartKey(item))));}refreshCartCount(container);openModal({title:'체험 내역을 저장했어요',body:'<p>선택한 상품과 수량을 이 브라우저에 저장했습니다.</p><p class="sf-prototype-note">실제 주문이나 결제는 접수하지 않았습니다. 배송·파일 다운로드·DB 사용권은 제공되지 않습니다.</p>',footer:'<button class="btn primary" data-done>확인</button>',onMount:d=>d.querySelector('[data-done]').onclick=closeModal});}catch{toast('브라우저 저장 공간을 사용할 수 없어 체험 내역을 저장하지 못했어요.');}};}});}
export function renderStorefront(container,ctx,parts=[]){disposeDetail();const section=['files','bstore','pod'].includes(parts[1])?parts[1]:'files';const id=parts[2];if(id&&section!=='files'){const p=findProduct(section,id);if(p){renderDetail(container,ctx,section,p);return;}container.innerHTML=`<div class="sf-workspace">${header(section)}${renderEmpty('상품을 찾을 수 없어요.')}<a class="btn" href="#shop/${section}">목록으로</a></div>`;container.querySelector('[data-cart]').onclick=()=>cartModal(container,ctx);return;}renderList(container,ctx,section);}
